#!/usr/bin/env bash
# run_skew_matrix.sh — the REAL two-end skew matrix (issue #1197, part
# of #908 P0).
#
# The supported core range is the generator's own major
# (lib/src/skew/skew_contract.dart). Proves that a slice generated by
# the CURRENT generator compiles against BOTH ends of that range:
#   - the OLDEST supported core: the lowest stable `v<major>.*` tag
#     (materialized via `git archive` into a temp dir — no checkout, no
#     worktree). Before the major's first release no such tag exists:
#     the old end IS this checkout, and the run says so.
#   - the NEWEST core: this checkout.
#
# And proves both gates end to end:
#   - MAJOR gate: against a core of the PREVIOUS major, `zfa make` is
#     REFUSED (exit 1, the re-pin prescription) and writes NO files;
#   - SURFACE gate: against a core that lacks a floored surface, the
#     skin kit and the simulation-coupled DI emission are REFUSED
#     (exit 1, `--> fix: dart pub upgrade zuraffa`) and write NO files,
#     while the skin kit is emitted on this checkout.
#
# No Flutter SDK needed: the generated legs are pure-Dart slices
# (entity + usecase + repository + datasource DI), analyzed with
# `dart analyze`. The Flutter-consumer gate (analyzer-family regular
# dep bumps, #1189) runs separately in CI — tools/flutter_consumer_smoke.sh.
#
# Usage:  tools/run_skew_matrix.sh
# Exit 0 iff every leg holds. CI: .github/workflows/skew-matrix.yaml
set -euo pipefail

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
cd "$ROOT"

WORK="$(mktemp -d /tmp/zfa1197_matrix.XXXXXX)"
trap 'rm -rf "$WORK"' EXIT

# Everything below keys off the generator's own version: the floor, the
# major under test and the previous major are never literals here.
GEN_VERSION="$(awk '/^version:/{print $2; exit}' pubspec.yaml)"
MAJOR="${GEN_VERSION%%.*}"
PREV_MAJOR=$((MAJOR - 1))
FLOOR="$MAJOR.0.0"

# Stable tags of one major, oldest first (pre-release tags excluded: a
# caret constraint never resolves them). `|| true`: an empty major must
# yield an empty list, not trip pipefail.
stable_tags() {
  { git tag --list "v$1.*" | grep -v -- '-' || true; } \
    | sort -t. -k1.2,1n -k2,2n -k3,3n
}

OLD_TAG="${SKEW_OLD_TAG:-$(stable_tags "$MAJOR" | head -1)}"
PREV_TAG="${SKEW_PREV_TAG:-$(stable_tags "$PREV_MAJOR" | tail -1)}"
if [ -z "$PREV_TAG" ]; then
  echo "FATAL: no stable v$PREV_MAJOR.* tag — the major-refusal leg needs a previous-major core"; exit 2
fi

# The consumer resolves the same annotation major this package does.
ZORPHY_ANN="$(awk '/^  zorphy_annotation:/{print $2; exit}' pubspec.yaml)"
ZORPHY="$(awk '/^  zorphy:/{print $2; exit}' pubspec.yaml)"

echo "== skew matrix: generator=$GEN_VERSION tag=${OLD_TAG:-<none: pre-release>} prev=$PREV_TAG work=$WORK"

# ---------------------------------------------------------------------------
# 1. Materialize the core ends (git archive — full history available in CI)
# ---------------------------------------------------------------------------
materialize() { # <git ref> <dest>
  rm -rf "$2"
  mkdir -p "$2"
  git archive "$1" lib pubspec.yaml | tar -x -C "$2"
  if [ ! -f "$2/lib/zuraffa.dart" ]; then
    echo "FATAL: $1 materialization failed (no lib/zuraffa.dart)"; exit 2
  fi
}

if [ -n "$OLD_TAG" ]; then
  OLD_CORE="$WORK/old-core"
  materialize "$OLD_TAG" "$OLD_CORE"
  echo "old core: $OLD_CORE ($OLD_TAG, pubspec $(awk '/^version:/{print $2; exit}' "$OLD_CORE/pubspec.yaml"))"
else
  OLD_CORE="$ROOT"
  echo "old core: this checkout — no stable v$MAJOR.* tag is published yet, so the two ends coincide"
fi

# A core from BEFORE the surface floors, for the surface-refusal legs:
# this checkout minus the gated surfaces. No such core exists inside
# the supported major today (both surfaces predate it); this is the
# shape of the first consumer a later minor leaves behind.
GATED_CORE="$WORK/gated-core"
materialize HEAD "$GATED_CORE"
rm -f "$GATED_CORE/lib/skin.dart" "$GATED_CORE/lib/simulation.dart"

# ---------------------------------------------------------------------------
# 2. Consumer package skeleton (deps mirror a real generated app — the
#    entity goes through zorphy codegen, so the legs are full-fidelity).
#    The previous major's core pins the previous annotation major, so
#    its consumer declares no zorphy range of its own.
# ---------------------------------------------------------------------------
make_consumer() { # <core> <dest> <with-zorphy: yes|no>
  local core="$1" dest="$2" zorphy_deps="$3"
  rm -rf "$dest"
  mkdir -p "$dest/lib"
  local zorphy_ann="" zorphy_dev=""
  if [ "$zorphy_deps" = yes ]; then
    zorphy_ann="  zorphy_annotation: $ZORPHY_ANN"
    zorphy_dev="  zorphy: $ZORPHY"
  fi
  cat > "$dest/pubspec.yaml" <<YAML
name: skew_consumer
publish_to: none
environment:
  sdk: ^3.11.0
dependencies:
  zuraffa:
    path: $core
$zorphy_ann
  meta: ^1.17.0
dev_dependencies:
  build_runner: ^2.15.2
$zorphy_dev
  json_serializable: ^6.13.2
dependency_overrides:
  # source_helper 1.4.0 duplicates extensions json_serializable 6.15.0 also
  # defines, so the consumer's build script fails to compile (#1937).
  source_helper: ">=1.3.10 <1.4.0"
YAML
}

# AOT-compile the generator once from source (fast, deterministic).
echo "compiling generator..."
dart pub get --no-example >/dev/null 2>&1 || dart pub get --no-example
dart compile exe bin/zfa.dart -o "$WORK/zfa" >/dev/null 2>&1 || {
  echo "FATAL: generator compile failed"; exit 2; }

# The pure-Dart slice: entity (with zorphy codegen) + usecase +
# repository + datasource — the two-end-stable surface. `di` is
# deliberately NOT in the slice: the datasource DI registration files
# import package:zuraffa/simulation.dart, a floor-registered surface
# the [di-refusal] leg proves the gate refuses on a core lacking it.
generate_slice() { # <consumer> <zfa binary>
  (cd "$1" && "$2" entity create -n Todo >/dev/null)
  (cd "$1" && dart run build_runner build >/dev/null 2>&1)
  (cd "$1" && "$2" make Todo \
      --methods=get,create \
      --with=repository,datasource,usecase >/dev/null)
  (cd "$1" && dart run build_runner build >/dev/null 2>&1)
}

run_leg() { # <core> <label>
  local core="$1" label="$2"
  local consumer="$WORK/consumer-$label"
  make_consumer "$core" "$consumer" yes
  echo "-- leg <$label>: core=$core"
  (cd "$consumer" && dart pub get >/dev/null 2>&1)
  generate_slice "$consumer" "$WORK/zfa"

  # Floor-stamped receipt proof (issue #1197).
  local receipt
  receipt="$(find "$consumer/.zfa/receipts" -name '*make-*.json' | head -1)"
  if [ -z "$receipt" ]; then
    echo "   FATAL: no make receipt written"; return 1
  fi
  python3 - "$receipt" "$FLOOR" <<'PY'
import json, sys
r = json.load(open(sys.argv[1]))
assert r.get('min_core_version'), f"receipt missing min_core_version: {r.get('min_core_version')}"
assert r['min_core_version'] == sys.argv[2], f"receipt floor {r['min_core_version']} != generator floor {sys.argv[2]}"
print(f"   receipt stamp ok: min_core_version={r['min_core_version']} generated_against_core={r.get('generated_against_core')}")
PY

  if (cd "$consumer" && dart analyze >/dev/null 2> "$WORK/analyze-$label.txt"); then
    echo "   dart analyze: CLEAN against $label core"
  else
    echo "   dart analyze: FAILED against $label core:" >&2
    sed -n '1,25p' "$WORK/analyze-$label.txt" >&2
    return 1
  fi
}

# ---------------------------------------------------------------------------
# 3. The gates, live.
# ---------------------------------------------------------------------------

# MAJOR gate: the previous major's core has every file with the old API
# shape. The generator refuses the whole emission up front.
major_refusal_leg() {
  local consumer="$WORK/consumer-major-refusal" core="$WORK/prev-core"
  materialize "$PREV_TAG" "$core"
  make_consumer "$core" "$consumer" no
  (cd "$consumer" && dart pub get >/dev/null 2>&1)
  (cd "$consumer" && "$WORK/zfa" entity create -n Todo >/dev/null)
  local before after
  before="$(cd "$consumer" && find lib -type f | sort)"
  set +e
  (cd "$consumer" && "$WORK/zfa" make Todo --methods=get,create \
      > "$WORK/major-refusal.out" 2> "$WORK/major-refusal.err")
  local rc=$?
  set -e
  local fatal=0
  if [ $rc -eq 0 ]; then
    echo "-- leg [major-refusal]: FATAL — make was NOT refused on $PREV_TAG"; fatal=1
  fi
  if ! cat "$WORK/major-refusal.out" "$WORK/major-refusal.err" \
      | grep -q "emits the $MAJOR.x core API"; then
    echo "-- leg [major-refusal]: FATAL — refusal does not name the major skew:" >&2
    cat "$WORK/major-refusal.out" "$WORK/major-refusal.err" >&2; fatal=1
  fi
  if ! cat "$WORK/major-refusal.out" "$WORK/major-refusal.err" \
      | grep -q "zuraffa: \^$FLOOR"; then
    echo "-- leg [major-refusal]: FATAL — refusal lacks the re-pin prescription:" >&2
    cat "$WORK/major-refusal.out" "$WORK/major-refusal.err" >&2; fatal=1
  fi
  after="$(cd "$consumer" && find lib -type f | sort)"
  if [ "$before" != "$after" ]; then
    echo "-- leg [major-refusal]: FATAL — files written despite refusal:" >&2
    diff <(echo "$before") <(echo "$after") >&2; fatal=1
  fi
  if [ -n "$(find "$consumer/.zfa/receipts" -name '*make-*.json' 2>/dev/null)" ]; then
    echo "-- leg [major-refusal]: FATAL — make receipt written despite refusal"; fatal=1
  fi
  if [ $fatal -ne 0 ]; then return 1; fi
  echo "-- leg [major-refusal]: refused on $PREV_TAG (exit $rc) with the re-pin prescription, no files written"
}

# SURFACE gate: a core that lacks skin.dart refuses the skin kit.
skin_refusal_leg() {
  local consumer="$WORK/consumer-skin-refusal"
  make_consumer "$GATED_CORE" "$consumer" yes
  (cd "$consumer" && dart pub get >/dev/null 2>&1)
  set +e
  (cd "$consumer" && "$WORK/zfa" skin kit --route home \
      > "$WORK/skin-kit.out" 2> "$WORK/skin-kit.err")
  local rc=$?
  set -e
  if [ $rc -eq 0 ]; then
    echo "-- leg [skin-refusal]: FATAL — skin kit emission was NOT refused on a core without skin.dart"; return 1
  fi
  if ! cat "$WORK/skin-kit.out" "$WORK/skin-kit.err" \
      | grep -q "dart pub upgrade zuraffa"; then
    echo "-- leg [skin-refusal]: FATAL — refusal lacks the prescription:" >&2
    cat "$WORK/skin-kit.out" "$WORK/skin-kit.err" >&2; return 1
  fi
  if [ -f "$consumer/lib/src/skin/skin_contract_auditor.dart" ]; then
    echo "-- leg [skin-refusal]: FATAL — kit file written despite refusal"; return 1
  fi
  echo "-- leg [skin-refusal]: refused on a core without skin.dart (exit $rc) with prescription, no files written"
}

# SURFACE gate: a core that lacks simulation.dart refuses the
# simulation-coupled DI emission (spec 893).
di_refusal_leg() {
  local consumer="$WORK/consumer-di-refusal"
  make_consumer "$GATED_CORE" "$consumer" yes
  (cd "$consumer" && dart pub get >/dev/null 2>&1)
  (cd "$consumer" && "$WORK/zfa" entity create -n Todo >/dev/null)
  (cd "$consumer" && dart run build_runner build >/dev/null 2>&1)
  set +e
  (cd "$consumer" && "$WORK/zfa" make Todo --methods=get,create \
      --with=repository,datasource,usecase,di \
      > "$WORK/di-refusal.out" 2> "$WORK/di-refusal.err")
  local rc=$?
  set -e
  if [ $rc -eq 0 ]; then
    echo "-- leg [di-refusal]: FATAL — simulation-coupled DI was NOT refused on a core without simulation.dart"; return 1
  fi
  if ! cat "$WORK/di-refusal.out" "$WORK/di-refusal.err" \
      | grep -q "dart pub upgrade zuraffa"; then
    echo "-- leg [di-refusal]: FATAL — refusal lacks the prescription:" >&2
    cat "$WORK/di-refusal.out" "$WORK/di-refusal.err" >&2; return 1
  fi
  echo "-- leg [di-refusal]: refused on a core without simulation.dart (exit $rc) with prescription"
}

# The skin kit on this checkout proceeds — generation only; compiling
# the Flutter kit is the CI flutter-smoke-gate's job.
skin_checkout_leg() {
  local consumer="$WORK/consumer-skin-checkout"
  make_consumer "$ROOT" "$consumer" yes
  (cd "$consumer" && dart pub get >/dev/null 2>&1)
  set +e
  (cd "$consumer" && "$WORK/zfa" skin kit --route home >/dev/null 2>&1)
  local rc=$?
  set -e
  if [ $rc -ne 0 ]; then
    echo "-- leg [skin-checkout]: FATAL — skin kit emission refused on this checkout (exit $rc)"; return 1
  fi
  [ -f "$consumer/lib/src/skin/skin_contract_auditor.dart" ] || {
    echo "-- leg [skin-checkout]: FATAL — kit file missing after success"; return 1; }
  echo "-- leg [skin-checkout]: kit emitted on this checkout (compile covered by flutter-smoke-gate)"
}

# ---------------------------------------------------------------------------
# 4. Run the matrix
# ---------------------------------------------------------------------------
FAILED=0
run_leg "$OLD_CORE" old        || FAILED=1
run_leg "$ROOT"     checkout   || FAILED=1
major_refusal_leg               || FAILED=1
skin_refusal_leg                || FAILED=1
di_refusal_leg                  || FAILED=1
skin_checkout_leg               || FAILED=1

if [ $FAILED -ne 0 ]; then
  echo "== skew matrix: RED (see above)"; exit 1
fi
echo "== skew matrix: GREEN — slice compiles on both ends; the major and surface gates are live"
